module snuke_deque(input [3:0] N,input [3:0] K,output reg [31:0] result);localparam MOD=1000000007;function [31:0] comb;input [3:0] n, r;integer i, acc;begin if(r>n)return 0;if(r==0)return 1;acc=1;for(i=1;i<=r;i++)begin acc=acc*(n-i+1)/i;end return acc%MOD;end function [31:0] pow2;input [3:0] exp;integer i,result;begin result=1;for(i=0;i<exp;i++)begin result=result*2%MOD;end return result;end assign result=(K==1)?(N==1?1:(N>1?pow2(N-2):0)):(K==N)?(N==1?1:(N>1?pow2(N-2):0)):0;endmodule